// api.ts
import { authService } from './authService';

const API_BASE_URL = 'http://localhost:8001';

export interface UploadResponse {
  id: string;
  name: string;
  url: string;
  detections: Array<{
    type: string;
    bbox: [number, number, number, number];
  }>;
  redactions: any[];
}

export interface FileInfo {
  object_name: string;
  size: number;
  last_modified: string;
  url: string;
  name?: string;
}

class ApiService {
  private async getAuthHeader(): Promise<HeadersInit> {
    const token = localStorage.getItem('token');
    
    if (token) {
      if (authService.isTokenExpired(token)) {
        console.warn('⚠️ Token expired');
        localStorage.removeItem('token');
        localStorage.removeItem('user');
        throw new Error('Session expired. Please login again.');
      }
      
      return { 
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      };
    }
    
    throw new Error('No authentication token found. Please login.');
  }

  private async getAuthHeaderForFormData(): Promise<HeadersInit> {
    const token = localStorage.getItem('token');
    
    if (token && !authService.isTokenExpired(token)) {
      return { 'Authorization': `Bearer ${token}` };
    }
    
    throw new Error('No valid authentication token found');
  }

  async uploadFiles(files: FileList): Promise<UploadResponse[]> {
    console.log(`🔄 Uploading ${files.length} file(s) to server...`);
    
    const formData = new FormData();
    
    for (let i = 0; i < files.length; i++) {
      formData.append('files', files[i]);
    }

    const headers = await this.getAuthHeaderForFormData();

    const response = await fetch(`${API_BASE_URL}/upload-multiple`, {
      method: 'POST',
      body: formData,
      headers: headers,
    });

    if (response.status === 401) {
      console.error('❌ Authentication required');
      this.clearAuth();
      throw new Error('Authentication required. Please login again.');
    }

    if (!response.ok) {
      const errorText = await response.text();
      console.error('❌ Upload error:', errorText);
      throw new Error(`Upload failed: ${errorText}`);
    }

    const result = await response.json();
    console.log(`✅ Upload successful: ${result.length} file(s) uploaded`);
    return result;
  }

  async uploadFile(file: File): Promise<UploadResponse> {
    console.log(`🔄 Uploading file: ${file.name}`);
    
    const formData = new FormData();
    formData.append('file', file);

    const headers = await this.getAuthHeaderForFormData();

    const response = await fetch(`${API_BASE_URL}/upload`, {
      method: 'POST',
      body: formData,
      headers: headers,
    });

    if (response.status === 401) {
      this.clearAuth();
      throw new Error('Authentication required. Please login again.');
    }

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Upload failed: ${errorText}`);
    }

    const result = await response.json();
    console.log(`✅ File uploaded: ${result.name}`);
    return result;
  }

  async getUserFiles(): Promise<FileInfo[]> {
    console.log('🔄 Fetching user files...');
    
    try {
      const headers = await this.getAuthHeader();
      
      const response = await fetch(`${API_BASE_URL}/files`, {
        method: 'GET',
        headers: headers,
      });

      if (response.status === 401) {
        this.clearAuth();
        throw new Error('Authentication required');
      }

      if (!response.ok) {
        throw new Error('Failed to fetch files');
      }

      const files = await response.json();
      console.log(`✅ Found ${files.length} file(s)`);
      return files;
    } catch (error) {
      console.error('❌ Error fetching files:', error);
      return [];
    }
  }

  async deleteFile(objectName: string): Promise<boolean> {
    console.log(`🔄 Deleting file: ${objectName}`);
    
    try {
      const headers = await this.getAuthHeader();
      
      const response = await fetch(`${API_BASE_URL}/files/${encodeURIComponent(objectName)}`, {
        method: 'DELETE',
        headers: headers,
      });

      if (response.status === 401) {
        this.clearAuth();
        throw new Error('Authentication required');
      }

      if (!response.ok) {
        throw new Error('Failed to delete file');
      }

      console.log(`✅ File deleted: ${objectName}`);
      return true;
    } catch (error) {
      console.error('❌ Error deleting file:', error);
      throw error;
    }
  }

  async healthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${API_BASE_URL}/health`);
      if (response.ok) {
        const data = await response.json();
        console.log('✅ Health check:', data);
        return data.status === 'healthy';
      }
      return false;
    } catch (error) {
      console.error('❌ Health check failed:', error);
      return false;
    }
  }

  async systemInfo(): Promise<any> {
    try {
      const response = await fetch(`${API_BASE_URL}/info`);
      if (response.ok) {
        return await response.json();
      }
      throw new Error('Failed to get system info');
    } catch (error) {
      console.error('❌ Failed to get system info:', error);
      throw error;
    }
  }

  async minioHealthCheck(): Promise<boolean> {
    try {
      const response = await fetch(`${API_BASE_URL}/health`);
      if (response.ok) {
        const data = await response.json();
        return data.minio_connected === true;
      }
      return false;
    } catch (error) {
      console.error('❌ MinIO health check failed:', error);
      return false;
    }
  }

  async getUserStorageInfo(): Promise<any> {
    try {
      const headers = await this.getAuthHeader();
      
      const response = await fetch(`${API_BASE_URL}/users/me/minio-info`, {
        headers: headers,
      });

      if (response.ok) {
        return await response.json();
      }
      return null;
    } catch (error) {
      console.error('❌ Failed to get storage info:', error);
      return null;
    }
  }

  async debugSystemStatus(): Promise<any> {
    try {
      const response = await fetch(`${API_BASE_URL}/debug/system-status`);
      return await response.json();
    } catch (error) {
      console.error('❌ Debug error:', error);
      throw error;
    }
  }

  // Старые методы для обратной совместимости
  async listMinioFiles(): Promise<any> {
    console.warn('⚠️ listMinioFiles is deprecated, use getUserFiles instead');
    return this.getUserFiles();
  }

  async uploadFilesLocal(files: FileList): Promise<UploadResponse[]> {
    console.warn('⚠️ uploadFilesLocal is deprecated, use uploadFiles instead');
    return this.uploadFiles(files);
  }

  async uploadFileLocal(file: File): Promise<UploadResponse> {
    console.warn('⚠️ uploadFileLocal is deprecated, use uploadFile instead');
    return this.uploadFile(file);
  }

  async debugFiles(): Promise<any> {
    console.warn('⚠️ debugFiles is deprecated');
    return { files: [] };
  }

  private clearAuth(): void {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    console.log('🔒 Auth cleared');
  }
}

export const apiService = new ApiService();
